#!/usr/bin/env node
/**
 * exec-shim.mjs — Layer-3 OS PATH shim for `pkill`, `kill`, `killall`, `paseo`,
 * `gh`, and package managers (ADR 0016 §3, ADR 0019 §1).
 *
 * Lives in `<stateDir>/bin/<tool>` (generated by `ensureGitShim` in
 * `plugin/server/shell.ts`), ahead of `/usr/bin` and `/bin` on every seat's
 * `PATH`.
 *
 * Behavior when `PASEO_FACTORY_SEAT` or `PASEO_FACTORY_CORRELATION` is set:
 * - `pkill` / `killall` / `kill`: refuses killing `paseo`, `plugin-process`,
 *   `opencode`, or processes running from `<stateDir>` (exit 126 + log line in
 *   `<stateDir>/git-blocked.log`).
 * - `paseo`: refuses `paseo agent ...` and `paseo plugin ...` subcommands
 *   (`seat-paseo-tool-fence`), directing the seat to `paseo_factory` MCP tools.
 * - `gh`: refuses `gh pr merge`, `gh repo delete`, and `gh release` subcommands
 *   (`seat-write-fence`).
 * - All other invocations pass through transparently to the real binary on PATH.
 */
import { isMcpStdioLaunch } from "./mcp-launch-policy.mjs";
import { accessSync, appendFileSync, constants as fsConstants, existsSync, mkdirSync, realpathSync } from "node:fs";
import { homedir } from "node:os";
import { delimiter, dirname, join } from "node:path";
import { spawn, spawnSync } from "node:child_process";
import { inheritChildOutcome } from "./process-policy.mjs";

const tool = process.argv[2] ?? "";
const argv = process.argv.slice(3);
if (process.env.PASEO_FACTORY_UI_HOME) {
  if (tool === 'agy') argv.unshift('--settings', join(process.env.PASEO_FACTORY_UI_HOME, 'agy-settings.json'));
  if (tool === 'copilot') argv.unshift('--plugin-dir', join(process.env.PASEO_FACTORY_UI_HOME, 'copilot'));
}
const stateDir = process.env.FACTORY_STATE_DIR ?? process.env.PASEO_FACTORY_STATE_DIR ?? "";
const REFUSAL_EXIT = 126;

if (tool === "") {
  console.error("exec-shim: missing target tool name");
  process.exit(2);
}

function isExecutable(p) {
  try {
    accessSync(p, fsConstants.X_OK);
    return true;
  } catch {
    return false;
  }
}

function resolveRealBinary(binName) {
  if (binName === 'impeccable' && process.env.PASEO_FACTORY_IMPECCABLE && isExecutable(process.env.PASEO_FACTORY_IMPECCABLE)) return process.env.PASEO_FACTORY_IMPECCABLE;
  const skip = new Set([
    ...(stateDir ? [join(stateDir, "bin")] : []),
    dirname(process.argv[1] ?? ""),
  ]);
  for (const dir of (process.env.PATH ?? "").split(delimiter)) {
    if (dir === "" || dir === "." || skip.has(dir)) continue;
    const candidate = join(dir, binName);
    if (existsSync(candidate) && isExecutable(candidate)) return candidate;
  }
  const fallbacks = [
    join(homedir(), ".local", "bin", binName),
    `/opt/homebrew/bin/${binName}`,
    `/usr/local/bin/${binName}`,
    `/usr/bin/${binName}`,
    `/bin/${binName}`,
  ];
  return fallbacks.find((f) => existsSync(f) && isExecutable(f));
}

function recordAndRefuse(rule, reason) {
  const command = [tool, ...argv].join(" ");
  let cwd = process.cwd();
  try {
    cwd = realpathSync(cwd);
  } catch {
    // keep process.cwd()
  }
  if (stateDir !== "") {
    const block = {
      id: `${Date.now().toString(36)}-${process.pid.toString(36)}-${Math.random().toString(36).slice(2, 10)}`,
      ts: new Date().toISOString(),
      command,
      rule,
      reason,
      cwd,
      ...(process.env.PASEO_AGENT_ID ? { agent: process.env.PASEO_AGENT_ID } : {}),
    };
    try {
      mkdirSync(stateDir, { recursive: true });
      appendFileSync(join(stateDir, "git-blocked.log"), `${JSON.stringify(block)}\n`);
    } catch {
      // still refuse even if audit log fails
    }
  }
  process.stderr.write(`paseo-factory refused (${rule}): ${reason} — nothing was executed.\n`);
  process.exit(REFUSAL_EXIT);
}

const seat = (process.env.PASEO_FACTORY_SEAT ?? "").trim();
const corr = (process.env.PASEO_FACTORY_CORRELATION ?? "").trim();
const inFactorySeat = seat !== "" || corr !== "";

// The Scrum specialization comes from the frozen Contract identity, never the CLI.
if (inFactorySeat && tool === 'impeccable' && process.env.PASEO_FACTORY_EXECUTION) {
  let identity;
  try { identity = JSON.parse(process.env.PASEO_FACTORY_EXECUTION); } catch { recordAndRefuse('policy:scrum-ui-capability', 'invalid Scrum identity'); }
  if (identity.kind !== 'task' || !['ux', 'dev', 'qa'].includes(identity.binding?.role)) recordAndRefuse('policy:scrum-ui-capability', 'impeccable is scoped to UX, Dev and QA');
}

// Package installs belong in isolated Task worktrees, never orchestration seats.
const packageTools = new Set(["npm", "npx", "pnpm", "yarn", "bun"]);
const packageMutations = new Set([
  "install", "i", "add", "ci", "remove", "rm", "uninstall", "update", "up", "upgrade",
  "link", "unlink", "init", "create", "dlx", "x",
]);
if ((seat === "supervisor" || seat === "lead") && packageTools.has(tool)) {
  const valueFlags = new Set([
    "--prefix", "--cache", "--registry", "--userconfig", "--globalconfig", "--location", "--workspace", "-w",
    "--dir", "-C", "--cwd", "--filter", "-F", "--store-dir", "--modules-dir", "--config",
    "--cache-folder", "--mutex", "--network-timeout", "--use-yarnrc",
    "--loglevel", "--logs-dir", "--tag", "--access", "--omit", "--include", "--before",
    "--script-shell", "--node-options", "--fetch-retries", "--fetch-timeout",
    "--cafile", "--cert", "--key", "--proxy", "--https-proxy", "--noproxy",
  ]);
  // Only a known command boundary makes subsequent words arguments/scripts.
  // Unknown configuration options may consume a value: neither an unfamiliar
  // option nor its first positional value proves that a later install is safe.
  const commandBoundaries = new Set([
    "run", "run-script", "test", "t", "start", "stop", "restart", "view", "info", "show",
    "ls", "list", "outdated", "why", "explain", "help", "root", "prefix", "bin",
    "ping", "doctor", "completion", "search",
  ]);
  const booleanFlags = new Set(["--global", "-g", "--silent", "--verbose", "--offline", "--version", "-v", "--help", "-h"]);
  let sub;
  let possibleOptionValue = false;
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (valueFlags.has(arg)) { i += 1; continue; }
    if (arg.startsWith("-")) {
      possibleOptionValue = !arg.includes("=") && !booleanFlags.has(arg);
      continue;
    }
    if (packageMutations.has(arg)) { sub = arg; break; }
    if (possibleOptionValue) { possibleOptionValue = false; continue; }
    if (commandBoundaries.has(arg)) { sub = arg; break; }
  }
  const informational = argv.some((arg) => ["--version", "-v", "--help", "-h"].includes(arg));
  if ((tool === "npx" && !isMcpStdioLaunch(argv)) || (tool === "yarn" && sub === undefined && !informational) || packageMutations.has(sub)) {
    const guidance = seat === "supervisor"
      ? "Supervisor must dispatch repairs via supervisor_dispatch_lead"
      : "Lead must contract and spawn a Task Agent via lead_set_contract + lead_spawn_agent";
    recordAndRefuse("seat-write-fence", `${tool} package mutation is forbidden in this seat; ${guidance}`);
  }
}

if (inFactorySeat) {
  const protectedPattern = /plugin-process|paseo|opencode/i;
  if (tool === "pkill" || tool === "killall") {
    const joined = argv.join(" ");
    if (protectedPattern.test(joined) || (stateDir !== "" && joined.includes(stateDir))) {
      recordAndRefuse(
        "seat-write-fence",
        `${tool} targeting Paseo/plugin-process or factory state is forbidden inside a factory seat`,
      );
    }
  } else if (tool === "kill") {
    const joined = argv.join(" ");
    if (protectedPattern.test(joined)) {
      recordAndRefuse(
        "seat-write-fence",
        `kill targeting Paseo/plugin-process is forbidden inside a factory seat`,
      );
    }
    const pids = [];
    for (let i = 0; i < argv.length; i++) {
      const tok = argv[i];
      if (tok === "-s" || tok === "-n") {
        i += 1;
        continue;
      }
      if (/^\d+$/.test(tok)) {
        pids.push(tok);
      } else if (/^-\d+$/.test(tok) && i > 0) {
        // Negative PID (process group) after flags
        pids.push(tok.slice(1));
      }
    }
    for (const pid of pids) {
      try {
        const ps = spawnSync("ps", ["-p", pid, "-o", "command="], { encoding: "utf8", timeout: 1_500 });
        const cmdline = (ps.stdout ?? "").trim();
        if (protectedPattern.test(cmdline) || (stateDir !== "" && cmdline.includes(stateDir))) {
          recordAndRefuse(
            "seat-write-fence",
            `kill targeting PID ${pid} (${cmdline.slice(0, 80)}) is forbidden inside a factory seat`,
          );
        }
      } catch {
        // ignore ps lookup failure
      }
    }
  } else if (tool === "paseo") {
    const valueFlags = new Set(["--home", "--profile", "--config", "-C"]);
    const positional = [];
    for (let i = 0; i < argv.length; i++) {
      const tok = argv[i];
      if (valueFlags.has(tok)) {
        i += 1;
        continue;
      }
      if (tok.startsWith("-")) continue;
      positional.push(tok);
    }
    const sub = positional[0];
    if (sub === "agent" || sub === "agents" || sub === "plugin" || sub === "plugins") {
      recordAndRefuse(
        "seat-paseo-tool-fence",
        `direct 'paseo ${sub}' CLI calls are forbidden inside a factory seat — use paseo_factory MCP tools instead`,
      );
    }
  } else if (tool === "gh") {
    const valueFlags = new Set(["-R", "--repo", "--hostname"]);
    const positional = [];
    for (let i = 0; i < argv.length; i++) {
      const tok = argv[i];
      if (valueFlags.has(tok)) {
        i += 1;
        continue;
      }
      if (tok.startsWith("-")) continue;
      positional.push(tok);
    }
    const [sub1, sub2] = positional;
    if (
      (sub1 === "pr" && sub2 === "merge") ||
      (sub1 === "repo" && sub2 === "delete") ||
      sub1 === "release"
    ) {
      recordAndRefuse(
        "seat-write-fence",
        `'gh ${[sub1, sub2].filter(Boolean).join(" ")}' is forbidden inside a factory seat`,
      );
    }
  }
}

const realBin = resolveRealBinary(tool);
if (realBin === undefined) {
  console.error(`exec-shim: could not find real '${tool}' on PATH`);
  process.exit(127);
}

const child = spawn(realBin, argv, { stdio: "inherit" });
inheritChildOutcome(child, (err) => {
  console.error(`exec-shim: failed to exec ${realBin}: ${err.message}`);
});
